CREATE OR REPLACE VIEW public.masked_donations WITH (security_barrier=true) AS SELECT d.id,d.fundraiser_id,d.user_id,CASE WHEN d.is_anonymous THEN 'Anonymous' ELSE d.donor_name END donor_name,d.amount,d.is_anonymous,d.message,d.created_at,NULL::text stripe_session_id,NULL::text donor_email,d.status,CASE WHEN d.is_anonymous THEN NULL ELSE public.mask_donor_phone(d.donor_phone) END donor_phone,d.payment_method FROM public.donations d WHERE d.user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.fundraisers f JOIN public.memorials m ON m.id=f.memorial_id WHERE f.id=d.fundraiser_id AND ((d.status='paid' AND m.is_public AND f.status='approved' AND f.is_active) OR public.is_memorial_admin(m.id,auth.uid()) OR public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.validate_privacy_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN PERFORM pg_advisory_xact_lock(hashtext(lower(NEW.email))); IF (SELECT count(*) FROM public.privacy_requests WHERE lower(email)=lower(NEW.email) AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Too many requests. Please contact the privacy team directly.'; END IF; NEW.created_at:=now(); NEW.status:='open'; NEW.closed_at:=NULL; NEW.legal_hold:=false; ELSE IF NEW.status='closed' AND OLD.status<>'closed' THEN NEW.closed_at:=now(); ELSIF NEW.status<>'closed' THEN NEW.closed_at:=NULL; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_privacy_request BEFORE INSERT OR UPDATE ON public.privacy_requests FOR EACH ROW EXECUTE FUNCTION public.validate_privacy_request();
CREATE OR REPLACE FUNCTION public.require_memorial_family_consent() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.is_public AND (TG_OP='INSERT' OR NOT OLD.is_public) AND EXISTS(SELECT 1 FROM public.family_members f WHERE f.memorial_id=NEW.id AND f.privacy_mode<>'family') AND NOT NEW.family_consent_confirmed THEN RAISE EXCEPTION 'Confirm living-relative and guardian consent before publishing family information'; END IF; RETURN NEW; END $$;
CREATE TRIGGER require_memorial_family_consent BEFORE INSERT OR UPDATE OF is_public,family_consent_confirmed ON public.memorials FOR EACH ROW EXECUTE FUNCTION public.require_memorial_family_consent();